mapper.select:
SELECT

FROM SysRoleInfo a left join SysUserInfo b
on b.id = a.createBy
WHERE 1 = 1

    and a.roleCode like CONCAT('%',#{roleCode}, '%')


    and a.roleName like CONCAT('%',#{roleName}, '%')


    and a.createBy = #{createBy}


    and a.createDate = #{createDate}


    and a.updateBy = #{updateBy}


    and a.updateDate = #{updateDate}
